@startuml

enum Suit {
  Diamonds
  Hearts
  Spades
  Clubs
}

enum ComparisonResult {
  Lower
  Equal
  Higher
}

enum SoloType {
  Trump
  Jack
  Queen
}

abstract class GameObject {
  + id : string
}

class Game {
  + gameId : string
}

class Card {
  + rank : int
  + suit : Suit
  + compareHeight(otherCard : Card) : ComparisonResult
}

class Deck {
  + cardCount : int
}

class ScoringTable {
  + tableId : string
}

class Round {
  + roundNumber : int
}

class SoloRound {
  + soloType : SoloType
}

class MandatorySoloRound --|> SoloRound

class Player {
  + playerName : string
}

class PointValue {
  + value : int
}

GameObject --|> Game
GameObject --|> Card
GameObject --|> Deck
GameObject --|> ScoringTable
GameObject --|> Round
GameObject --|> SoloRound
GameObject --|> Player
GameObject --|> PointValue

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable

Deck "1" *-- "0..48" Card

ScoringTable "1" *-- "1..*" Round

Round "1" *-- "0..*" PointValue
Round "1" *-- "0..*" Player
Round "1" *-- "0..*" SoloRound

SoloRound "1" *-- "1" Player
@enduml

